--
-- Table structure for table `dp5_bookly_mailing_campaigns`
--

DROP TABLE IF EXISTS `dp5_bookly_mailing_campaigns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dp5_bookly_mailing_campaigns` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `mailing_list_id` int(10) unsigned DEFAULT NULL,
  `audience` text DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `text` text DEFAULT NULL,
  `state` enum('pending','in-progress','completed','canceled') NOT NULL DEFAULT 'pending',
  `send_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `mailing_list_id` (`mailing_list_id`),
  CONSTRAINT `dp5_bookly_mailing_campaigns_ibfk_1` FOREIGN KEY (`mailing_list_id`) REFERENCES `dp5_bookly_mailing_lists` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
