  `plugin_id` int(10) unsigned NOT NULL,
  `highlighted` tinyint(1) NOT NULL DEFAULT 0,
  `priority` int(10) unsigned DEFAULT 0,
  `demo_url` varchar(255) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `url` varchar(255) NOT NULL,
  `icon` varchar(255) NOT NULL,
  `image` varchar(255) NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `sub_price` varchar(64) DEFAULT NULL,
  `sales` int(10) unsigned NOT NULL,
  `rating` decimal(10,2) NOT NULL,
  `reviews` int(10) unsigned NOT NULL,
  `published` datetime NOT NULL,
  `seen` tinyint(1) NOT NULL DEFAULT 0,
  `license` varchar(32) DEFAULT NULL,
  `content` text DEFAULT NULL,
  `bundle_plugins` text DEFAULT NULL,
  `visible` tinyint(4) DEFAULT 1,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

