DROP TABLE IF EXISTS `dp5_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dp5_posts` (
  `ID` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint(20) unsigned NOT NULL DEFAULT 0,
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext NOT NULL,
  `post_title` text NOT NULL,
  `post_excerpt` text NOT NULL,
  `post_status` varchar(20) NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) NOT NULL DEFAULT 'open',
  `post_password` varchar(255) NOT NULL DEFAULT '',
  `post_name` varchar(200) NOT NULL DEFAULT '',
  `to_ping` text NOT NULL,
  `pinged` text NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext NOT NULL,
  `post_parent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `guid` varchar(255) NOT NULL DEFAULT '',
  `menu_order` int(11) NOT NULL DEFAULT 0,
  `post_type` varchar(20) NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) NOT NULL DEFAULT '',
  `comment_count` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=223 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `dp5_posts`
--

LOCK TABLES `dp5_posts` WRITE;
/*!40000 ALTER TABLE `dp5_posts` DISABLE KEYS */;
INSERT INTO `dp5_posts` VALUES (4,0,'2026-09-30 16:52:54','2026-09-30 16:52:54','<!-- wp:page-list /-->','Điều hướng','','publish','closed','closed','','navigation','','','2026-09-30 16:52:54','2026-09-30 16:52:54','',0,'http://localhost/dongphuc/2026/09/30/navigation/',0,'wp_navigation','',0),(6,1,'2026-09-30 16:58:32','2026-09-30 16:58:32','{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }','Custom Styles','','publish','closed','closed','','wp-global-styles-twentytwentyfive','','','2026-09-30 16:58:32','2026-09-30 16:58:32','',0,'http://localhost/dongphuc/wp-global-styles-twentytwentyfive/',0,'wp_global_styles','',0),(9,1,'2026-09-30 19:20:07','2026-09-30 19:20:07','{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }','Custom Styles','','publish','closed','closed','','wp-global-styles-astra-child','','','2026-09-30 19:20:07','2026-09-30 19:20:07','',0,'http://localhost/dongphuc/wp-global-styles-astra-child/',0,'wp_global_styles','',0),(24,1,'2026-10-01 07:47:28','2026-10-01 07:47:28','<!-- wp:html -->\n<!-- wp:html -->\n<style>\n.venus-home {\n    font-family: Arial, sans-serif;\n    color: #292929;\n    line-height: 1.7;\n}\n.venus-home * { box-sizing: border-box; }\n.venus-home a { text-decoration: none; }\n.venus-home .vh-container {\n    width: 92%;\n    max-width: 1180px;\n    margin: auto;\n}\n.venus-home .vh-hero {\n    background: linear-gradient(110deg, #102B46, #173B5E);\n    color: white;\n    padding: 90px 7%;\n    text-align: left;\n}\n.venus-home .vh-hero h1 {\n    color: #fff;\n    font-size: clamp(32px, 5vw, 55px);\n    line-height: 1.2;\n    max-width: 750px;\n    margin: 0 0 20px;\n}\n.venus-home .vh-hero p {\n    color: #F3F5F7;\n    font-size: 18px;\n    max-width: 650px;\n}\n.venus-home .vh-btn {\n    display: inline-block;\n    background: #C9A45C;\n    color: #fff;\n    padding: 13px 25px;\n    margin: 12px 10px 0 0;\n    border-radius: 3px;\n    font-weight: bold;\n}\n.venus-home .vh-btn:hover {\n    background: #A9823F;\n    color: white;\n}\n.venus-home .vh-section { padding: 65px 0; }\n.venus-home .vh-title {\n    text-align: center;\n    margin-bottom: 35px;\n}\n.venus-home .vh-title h2 {\n    color: #102B46;\n    font-size: 30px;\n    margin-bottom: 8px;\n}\n.venus-home .vh-title p { color: #777; }\n\n.venus-home .vh-about {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 35px;\n    align-items: center;\n}\n.venus-home .vh-about-panel {\n    background: #F3F5F7;\n    padding: 35px;\n    border-left: 5px solid #C9A45C;\n}\n.venus-home .vh-about-panel h2 { color: #102B46; }\n\n.venus-home .vh-categories {\n    display: grid;\n    grid-template-columns: repeat(3, minmax(0, 1fr));\n    gap: 22px;\n}\n.venus-home .vh-category {\n    background: #F3F5F7;\n    padding: 12px 12px 22px;\n    text-align: center;\n    border-bottom: 3px solid #C9A45C;\n    border-radius: 5px;\n    overflow: hidden;\n}\n.venus-home .vh-category img {\n    display: block !important;\n    visibility: visible !important;\n    opacity: 1 !important;\n    width: 100% !important;\n    max-width: 100% !important;\n    height: 230px !important;\n    object-fit: cover !important;\n    border-radius: 4px;\n    margin: 0 0 15px !important;\n}\n.venus-home .vh-category h3 {\n    color: #102B46;\n    margin: 8px 0;\n    font-size: 19px;\n}\n.venus-home .vh-category p {\n    color: #666;\n    margin: 0;\n}\n\n.venus-home .vh-process { background: #F3F5F7; }\n.venus-home .vh-steps {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 18px;\n}\n.venus-home .vh-step {\n    background: white;\n    padding: 24px;\n    text-align: center;\n    border-radius: 4px;\n}\n.venus-home .vh-step strong {\n    display: block;\n    color: #C9A45C;\n    font-size: 30px;\n}\n.venus-home .vh-step h3 { color: #102B46; }\n\n.venus-home .vh-cta {\n    background: #102B46;\n    color: white;\n    text-align: center;\n    padding: 60px 20px;\n}\n.venus-home .vh-cta h2 { color: white; }\n.venus-home .vh-cta p { color: #eee; }\n\n.venus-home .vh-contact {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 20px;\n    text-align: center;\n}\n.venus-home .vh-contact > div {\n    background: #F3F5F7;\n    padding: 22px;\n    border-bottom: 3px solid #C9A45C;\n}\n.venus-home .vh-contact h3 { color: #102B46; }\n\n@media(max-width:700px) {\n    .venus-home .vh-about,\n    .venus-home .vh-categories,\n    .venus-home .vh-steps,\n    .venus-home .vh-contact {\n        grid-template-columns: 1fr;\n    }\n    .venus-home .vh-hero { padding: 60px 6%; }\n    .venus-home .vh-category img { height: 250px !important; }\n}\n</style>\n\n<div class=\"venus-home\">\n\n<!-- BANNER -->\n<section class=\"vh-hero\">\n    <div class=\"vh-container\">\n        <p>VENUS UNIFORM · ĐỒNG PHỤC DOANH NGHIỆP</p>\n        <h1>ĐỒNG PHỤC CHUYÊN NGHIỆP – KHẲNG ĐỊNH BẢN SẮC THƯƠNG HIỆU</h1>\n        <p>Giải pháp thiết kế và sản xuất đồng phục dành cho doanh nghiệp, trường học và tổ chức. Chỉn chu trong từng đường may, đồng bộ trong hình ảnh thương hiệu.</p>\n        <a class=\"vh-btn\" href=\"/dongphuc/dich-vu/\">KHÁM PHÁ SẢN PHẨM</a>\n        <a class=\"vh-btn\" href=\"/dongphuc/dat-lich-tu-van/\">ĐẶT LỊCH TƯ VẤN</a>\n    </div>\n</section>\n\n<!-- GIỚI THIỆU -->\n<section class=\"vh-section\">\n    <div class=\"vh-container vh-about\">\n        <div class=\"vh-about-panel\">\n            <h2>VENUS UNIFORM – ĐỒNG HÀNH CÙNG DOANH NGHIỆP</h2>\n            <p>Chúng tôi cung cấp giải pháp đồng phục giúp doanh nghiệp xây dựng hình ảnh chuyên nghiệp, thống nhất và tạo dấu ấn riêng.</p>\n            <p>Từ lựa chọn chất liệu, thiết kế kiểu dáng đến sản xuất, mỗi sản phẩm đều hướng tới sự thoải mái, phù hợp và chỉn chu.</p>\n            <a class=\"vh-btn\" href=\"/dongphuc/gioi-thieu/\">TÌM HIỂU THÊM</a>\n        </div>\n        <div>\n            <h2>Giải pháp đồng phục toàn diện</h2>\n            <p>• Tư vấn lựa chọn chất liệu phù hợp.</p>\n            <p>• Thiết kế theo nhận diện thương hiệu.</p>\n            <p>• Sản xuất theo nhu cầu và số lượng.</p>\n            <p>• Hỗ trợ tư vấn và báo giá cho doanh nghiệp.</p>\n        </div>\n    </div>\n</section>\n\n<!-- DANH MỤC ĐỒNG PHỤC -->\n<section class=\"vh-section\" style=\"background:#FFFFFF\">\n    <div class=\"vh-container\">\n        <div class=\"vh-title\">\n            <h2>DANH MỤC ĐỒNG PHỤC</h2>\n            <p>Đa dạng lựa chọn cho nhiều lĩnh vực hoạt động</p>\n        </div>\n\n        <div class=\"vh-categories\">\n            <div class=\"vh-category\">\n                <img src=\"/dongphuc/wp-content/uploads/anhthat/congso.jpg\" alt=\"Đồng phục công sở\">\n                <h3>Đồng phục công sở</h3>\n                <p>Chuyên nghiệp và thanh lịch.</p>\n            </div>\n            <div class=\"vh-category\">\n                <div style=\"width:100%;height:230px;background-image:url(\'http://localhost/dongphuc/wp-content/uploads/anhthat/yte.jpg\');background-size:cover;background-position:center;\"></div>\n                <h3>Đồng phục y tế &amp; spa</h3>\n                <p>Thoải mái, tiện dụng và chỉn chu.</p>\n            </div>\n            <div class=\"vh-category\">\n                <img src=\"/dongphuc/wp-content/uploads/anhthat/aothun.jpg\" alt=\"Áo thun\">\n                <h3>Áo thun &amp; sự kiện</h3>\n                <p>Đồng bộ hình ảnh tập thể.</p>\n            </div>\n            <div class=\"vh-category\">\n                <img src=\"/dongphuc/wp-content/uploads/anhthat/baoho.jpg\" alt=\"Đồng phục bảo hộ\">\n                <h3>Đồng phục bảo hộ</h3>\n                <p>Phù hợp môi trường làm việc.</p>\n            </div>\n            <div class=\"vh-category\">\n                <img src=\"/dongphuc/wp-content/uploads/anhthat/khachhsan.jpg\" alt=\"Đồng phục khách sạn\">\n                <h3>Nhà hàng &amp; khách sạn</h3>\n                <p>Gọn gàng và chuyên nghiệp.</p>\n            </div>\n            <div class=\"vh-category\">\n                <img src=\"/dongphuc/wp-content/uploads/anhthat/truonghoc.jpg\" alt=\"Đồng phục trường học\">\n                <h3>Đồng phục trường học</h3>\n                <p>Đồng bộ và năng động.</p>\n            </div>\n        </div>\n    </div>\n</section>\n\n<!-- SẢN PHẨM NỔI BẬT -->\n<div class=\"venus-products-section\">\n    <div class=\"vh-container\">\n        <div class=\"vh-title\">\n            <h2>SẢN PHẨM NỔI BẬT</h2>\n            <p>Khám phá các mẫu đồng phục của VENUS UNIFORM</p>\n        </div>\n    </div>\n    [products limit=\"8\" columns=\"4\" orderby=\"date\" order=\"DESC\"]\n    <div class=\"vh-container\" style=\"text-align:center\">\n        <a class=\"vh-btn\" href=\"/dongphuc/dich-vu/\">XEM TẤT CẢ SẢN PHẨM</a>\n    </div>\n</div>\n\n<!-- QUY TRÌNH -->\n<section class=\"vh-section vh-process\">\n    <div class=\"vh-container\">\n        <div class=\"vh-title\">\n            <h2>QUY TRÌNH TƯ VẤN VÀ ĐẶT HÀNG</h2>\n            <p>Đơn giản, rõ ràng và thuận tiện</p>\n        </div>\n        <div class=\"vh-steps\">\n            <div class=\"vh-step\">\n                <strong>01</strong>\n                <h3>Tiếp nhận yêu cầu</h3>\n                <p>Lắng nghe nhu cầu và số lượng đồng phục.</p>\n            </div>\n            <div class=\"vh-step\">\n                <strong>02</strong>\n                <h3>Tư vấn thiết kế</h3>\n                <p>Gợi ý kiểu dáng và chất liệu phù hợp.</p>\n            </div>\n            <div class=\"vh-step\">\n                <strong>03</strong>\n                <h3>Báo giá</h3>\n                <p>Trao đổi phương án và chi phí dự kiến.</p>\n            </div>\n            <div class=\"vh-step\">\n                <strong>04</strong>\n                <h3>Sản xuất</h3>\n                <p>Triển khai đơn hàng theo thỏa thuận.</p>\n            </div>\n        </div>\n    </div>\n</section>\n\n<!-- KÊU GỌI TƯ VẤN -->\n<section class=\"vh-cta\">\n    <div class=\"vh-container\">\n        <h2>BẠN ĐANG TÌM GIẢI PHÁP ĐỒNG PHỤC CHO DOANH NGHIỆP?</h2>\n        <p>Hãy liên hệ VENUS UNIFORM để được tư vấn và nhận báo giá.</p>\n        <a class=\"vh-btn\" href=\"/dongphuc/dat-lich-tu-van/\">ĐẶT LỊCH TƯ VẤN NGAY</a>\n        <a class=\"vh-btn\" href=\"/dongphuc/lien-he/\">LIÊN HỆ VỚI CHÚNG TÔI</a>\n    </div>\n</section>\n\n<!-- THÔNG TIN LIÊN HỆ -->\n<section class=\"vh-section\">\n    <div class=\"vh-container\">\n        <div class=\"vh-title\">\n            <h2>THÔNG TIN LIÊN HỆ</h2>\n        </div>\n        <div class=\"vh-contact\">\n            <div>\n                <h3>Địa chỉ</h3>\n                <p>Số 10 Phố Vọng, Hai Bà Trưng, Hà Nội</p>\n            </div>\n            <div>\n                <h3>Hotline</h3>\n                <p>0988 686 868</p>\n            </div>\n            <div>\n                <h3>Thời gian</h3>\n                <p>Thứ 2 – Thứ 7: 8:00 – 17:30</p>\n            </div>\n        </div>\n    </div>\n</section>\n\n</div>\n<!-- /wp:html -->\n<!-- /wp:html -->','Trang Chủ','','publish','closed','closed','','trang-chu','','','2026-11-03 19:12:22','2026-11-03 19:12:22','',0,'http://localhost/dongphuc/?page_id=24',0,'page','',0),(25,1,'2026-10-01 07:47:28','2026-10-01 07:47:28','<!-- wp:paragraph -->\n<p>Chào mừng đến với dịch vụ đồng phục doanh nghiệp</p>\n<!-- /wp:paragraph -->','Trang Chủ','','inherit','closed','closed','','24-revision-v1','','','2026-10-01 07:47:28','2026-10-01 07:47:28','',24,'http://localhost/dongphuc/?p=25',0,'revision','',0),(26,1,'2026-10-01 07:48:02','2026-10-01 07:48:02','<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\"></h1>\n<!-- /wp:heading -->\n\n<!-- wp:html -->\n<style>\n.venus-about {\n    --navy: #102B46;\n    --gold: #C9A45C;\n    --light: #F3F5F7;\n    color: #333;\n    font-family: Arial, sans-serif;\n    line-height: 1.7;\n}\n.venus-about * { box-sizing: border-box; }\n.venus-about .va-hero {\n    background: linear-gradient(120deg,#102B46,#1D4668);\n    color: white;\n    padding: 85px 25px;\n    text-align: center;\n}\n.venus-about .va-hero h1 {\n    color: white;\n    font-size: 42px;\n    margin: 0 0 15px;\n}\n.venus-about .va-hero p {\n    max-width: 750px;\n    margin: auto;\n    font-size: 18px;\n}\n.venus-about .va-wrap {\n    max-width: 1150px;\n    margin: auto;\n    padding: 65px 22px;\n}\n.venus-about .va-label {\n    color: #A9843F;\n    font-weight: bold;\n    letter-spacing: 2px;\n    text-transform: uppercase;\n    font-size: 13px;\n}\n.venus-about h2 {\n    color: var(--navy);\n    font-size: 30px;\n    line-height: 1.3;\n    margin: 10px 0 20px;\n}\n.venus-about .va-intro {\n    display: grid;\n    grid-template-columns: 1.1fr .9fr;\n    gap: 45px;\n    align-items: center;\n}\n.venus-about .va-intro-img {\n    min-height: 320px;\n    background: linear-gradient(145deg,#102B46,#52718B);\n    border-radius: 8px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: white;\n    text-align: center;\n    padding: 25px;\n}\n.venus-about .va-intro-img strong {\n    font-size: 30px;\n    letter-spacing: 3px;\n}\n.venus-about .va-grid {\n    display: grid;\n    grid-template-columns: repeat(3,1fr);\n    gap: 22px;\n    margin-top: 30px;\n}\n.venus-about .va-card {\n    background: white;\n    padding: 28px;\n    border-radius: 7px;\n    border-bottom: 3px solid var(--gold);\n    box-shadow: 0 5px 22px rgba(0,0,0,.06);\n}\n.venus-about .va-card h3 {\n    color: var(--navy);\n    margin-top: 0;\n    font-size: 20px;\n}\n.venus-about .va-fields {\n    background: var(--light);\n}\n.venus-about .va-fields .va-card {\n    border: 1px solid #e5e8ec;\n    border-bottom: 3px solid var(--gold);\n}\n.venus-about .va-number {\n    font-size: 30px;\n    font-weight: bold;\n    color: var(--gold);\n    margin-bottom: 10px;\n}\n.venus-about .va-commit {\n    background: var(--navy);\n    color: white;\n}\n.venus-about .va-commit h2 { color: white; }\n.venus-about .va-commit .va-card {\n    background: rgba(255,255,255,.08);\n    color: white;\n    box-shadow: none;\n}\n.venus-about .va-commit .va-card h3 { color: #E3C889; }\n.venus-about .va-cta {\n    background: #F3F5F7;\n    text-align: center;\n    padding: 60px 20px;\n}\n.venus-about .va-button {\n    display: inline-block;\n    background: var(--gold);\n    color: #102B46 !important;\n    padding: 13px 28px;\n    margin-top: 15px;\n    border-radius: 4px;\n    text-decoration: none;\n    font-weight: bold;\n}\n@media(max-width:768px) {\n    .venus-about .va-hero { padding: 60px 20px; }\n    .venus-about .va-hero h1 { font-size: 32px; }\n    .venus-about .va-intro { grid-template-columns: 1fr; }\n    .venus-about .va-grid { grid-template-columns: 1fr; }\n    .venus-about .va-wrap { padding: 45px 20px; }\n}\n</style>\n\n<div class=\"venus-about\">\n\n<section class=\"va-hero\">\n    <div class=\"va-label\" style=\"color:#E3C889\">VENUS UNIFORM</div>\n    <h1>VỀ CHÚNG TÔI</h1>\n    <p>Đồng hành cùng doanh nghiệp xây dựng hình ảnh chuyên nghiệp, đồng bộ và mang đậm bản sắc thương hiệu.</p>\n</section>\n\n<section class=\"va-wrap\">\n    <div class=\"va-intro\">\n        <div>\n            <div class=\"va-label\">CÂU CHUYỆN THƯƠNG HIỆU</div>\n            <h2>Đồng phục không chỉ là trang phục, đó còn là hình ảnh doanh nghiệp</h2>\n            <p>VENUS UNIFORM là thương hiệu chuyên cung cấp giải pháp đồng phục doanh nghiệp, hướng đến việc tạo nên những bộ trang phục chuyên nghiệp, đồng bộ và phù hợp với bản sắc riêng của từng tổ chức.</p>\n            <p>Chúng tôi hiểu rằng đồng phục không chỉ là trang phục làm việc mà còn thể hiện hình ảnh thương hiệu, văn hóa và sự gắn kết của doanh nghiệp.</p>\n        </div>\n        <div class=\"va-intro-img\">\n            <strong>VENUS<br>UNIFORM</strong>\n        </div>\n    </div>\n</section>\n\n<section class=\"va-wrap\" style=\"background:#fff\">\n    <div class=\"va-label\">ĐỊNH HƯỚNG PHÁT TRIỂN</div>\n    <h2>Sứ mệnh – Tầm nhìn – Giá trị cốt lõi</h2>\n    <div class=\"va-grid\">\n        <div class=\"va-card\">\n            <h3>Sứ mệnh</h3>\n            <p>Mang đến giải pháp đồng phục phù hợp, góp phần xây dựng hình ảnh chuyên nghiệp và sự tự tin cho mỗi doanh nghiệp.</p>\n        </div>\n        <div class=\"va-card\">\n            <h3>Tầm nhìn</h3>\n            <p>Trở thành thương hiệu đồng phục doanh nghiệp được khách hàng tin tưởng lựa chọn.</p>\n        </div>\n        <div class=\"va-card\">\n            <h3>Giá trị cốt lõi</h3>\n            <p>Chất lượng, tận tâm, chuyên nghiệp và luôn lắng nghe nhu cầu của khách hàng.</p>\n        </div>\n    </div>\n</section>\n\n<section class=\"va-fields\">\n    <div class=\"va-wrap\">\n        <div class=\"va-label\">GIẢI PHÁP CỦA CHÚNG TÔI</div>\n        <h2>Lĩnh vực hoạt động</h2>\n        <div class=\"va-grid\">\n            <div class=\"va-card\">\n                <div class=\"va-number\">01</div>\n                <h3>Đồng phục công sở</h3>\n                <p>Áo sơ mi, vest, chân váy và quần âu.</p>\n            </div>\n            <div class=\"va-card\">\n                <div class=\"va-number\">02</div>\n                <h3>Đồng phục y tế</h3>\n                <p>Áo blouse, đồng phục phòng khám và spa.</p>\n            </div>\n            <div class=\"va-card\">\n                <div class=\"va-number\">03</div>\n                <h3>Nhà hàng – khách sạn</h3>\n                <p>Đồng phục lễ tân, bếp và phục vụ.</p>\n            </div>\n            <div class=\"va-card\">\n                <div class=\"va-number\">04</div>\n                <h3>Áo thun đồng phục</h3>\n                <p>Áo polo, áo nhóm và áo teambuilding.</p>\n            </div>\n            <div class=\"va-card\">\n                <div class=\"va-number\">05</div>\n                <h3>Đồng phục bảo hộ</h3>\n                <p>Trang phục bảo hộ lao động và kỹ thuật.</p>\n            </div>\n        </div>\n    </div>\n</section>\n\n<section class=\"va-wrap va-commit\">\n    <div class=\"va-label\" style=\"color:#E3C889\">ĐIỀU CHÚNG TÔI CAM KẾT</div>\n    <h2>Giá trị tạo nên sự khác biệt</h2>\n    <div class=\"va-grid\">\n        <div class=\"va-card\">\n            <h3>Chất lượng</h3>\n            <p>Chú trọng chất liệu, đường may và độ bền sản phẩm.</p>\n        </div>\n        <div class=\"va-card\">\n            <h3>Thiết kế</h3>\n            <p>Tư vấn kiểu dáng phù hợp với đặc thù từng doanh nghiệp.</p>\n        </div>\n        <div class=\"va-card\">\n            <h3>Cá nhân hóa</h3>\n            <p>Hỗ trợ in, thêu logo và nhận diện thương hiệu.</p>\n        </div>\n        <div class=\"va-card\">\n            <h3>Tư vấn tận tâm</h3>\n            <p>Đồng hành cùng khách hàng từ khâu lựa chọn đến báo giá và sản xuất.</p>\n        </div>\n    </div>\n</section>\n\n<section class=\"va-cta\">\n    <div class=\"va-label\">VENUS UNIFORM</div>\n    <h2>Cùng doanh nghiệp xây dựng hình ảnh chuyên nghiệp</h2>\n    <p>Liên hệ với chúng tôi để được tư vấn giải pháp đồng phục phù hợp.</p>\n    <a class=\"va-button\" href=\"/dongphuc/dat-lich-tu-van/\">ĐẶT LỊCH TƯ VẤN</a>\n    <a class=\"va-button\" href=\"/dongphuc/lien-he/\" style=\"margin-left:10px;background:#102B46;color:white !important\">LIÊN HỆ</a>\n</section>\n\n</div>\n<!-- /wp:html -->','GIỚI THIỆU','','publish','closed','closed','','gioi-thieu','','','2026-11-03 19:51:37','2026-11-03 19:51:37','',0,'http://localhost/dongphuc/?page_id=26',0,'page','',0),(27,1,'2026-10-01 07:48:02','2026-10-01 07:48:02','<!-- wp:paragraph -->\n<p>Giới thiệu doanh nghiệp (sẽ cập nhật)</p>\n<!-- /wp:paragraph -->','Giới thiệu','','inherit','closed','closed','','26-revision-v1','','','2026-10-01 07:48:02','2026-10-01 07:48:02','',26,'http://localhost/dongphuc/?p=27',0,'revision','',0),(28,1,'2026-10-01 07:48:48','2026-10-01 07:48:48','','Sản phẩm','','publish','closed','closed','','dich-vu','','','2026-11-04 08:28:29','2026-11-04 08:28:29','',0,'http://localhost/dongphuc/?page_id=28',0,'page','',0),(29,1,'2026-10-01 07:48:48','2026-10-01 07:48:48','<!-- wp:paragraph -->\n<p>Danh mục dịch vụ(sẽ cập nhật)</p>\n<!-- /wp:paragraph -->','Dịch vụ','','inherit','closed','closed','','28-revision-v1','','','2026-10-01 07:48:48','2026-10-01 07:48:48','',28,'http://localhost/dongphuc/?p=29',0,'revision','',0),(30,1,'2026-10-01 07:49:17','2026-10-01 07:49:17','<!-- wp:html -->\n<style>\n.venus-price-page {\n    max-width: 1150px;\n    margin: 0 auto;\n    padding: 45px 20px;\n    color: #40382e;\n}\n.venus-price-hero {\n    text-align: center;\n    padding: 55px 25px;\n    background: #f5efe5;\n    border-radius: 12px;\n    margin-bottom: 45px;\n}\n.venus-price-hero h1 {\n    color: #8b6535;\n    font-size: 34px;\n}\n.venus-price-hero p {\n    max-width: 750px;\n    margin: 15px auto;\n    line-height: 1.8;\n}\n.venus-price-page h2 {\n    text-align: center;\n    color: #8b6535;\n    margin: 40px 0 25px;\n}\n.venus-price-table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 25px 0;\n}\n.venus-price-table th {\n    background: #342b20;\n    color: white;\n    padding: 16px;\n}\n.venus-price-table td {\n    border: 1px solid #e5ded2;\n    padding: 16px;\n    text-align: center;\n}\n.venus-price-table tr:nth-child(even) {\n    background: #faf7f2;\n}\n.venus-price-note {\n    background: #f8f3e9;\n    padding: 22px;\n    border-left: 4px solid #c49a58;\n    line-height: 1.8;\n    margin: 25px 0;\n}\n.venus-price-cta {\n    background: #342b20;\n    color: white;\n    padding: 40px 25px;\n    border-radius: 12px;\n    text-align: center;\n    margin-top: 45px;\n}\n.venus-price-cta h2 {\n    color: #e1bd80;\n    margin-top: 0;\n}\n.venus-price-cta a {\n    display: inline-block;\n    background: #c49a58;\n    color: white;\n    padding: 13px 28px;\n    border-radius: 5px;\n    text-decoration: none;\n    font-weight: bold;\n    margin-top: 15px;\n}\n@media(max-width:650px) {\n    .venus-price-table {\n        font-size: 13px;\n    }\n    .venus-price-table th,\n    .venus-price-table td {\n        padding: 9px 5px;\n    }\n    .venus-price-hero h1 {\n        font-size: 26px;\n    }\n}\n</style>\n\n<div class=\"venus-price-page\">\n    <section class=\"venus-price-hero\">\n        <h1>BẢNG GIÁ ĐỒNG PHỤC DOANH NGHIỆP</h1>\n        <p>VENUS UNIFORM cung cấp giải pháp đồng phục phù hợp với nhu cầu, ngân sách và hình ảnh thương hiệu của từng doanh nghiệp.</p>\n        <p>Liên hệ với chúng tôi để được tư vấn chất liệu, thiết kế và nhận báo giá chi tiết.</p>\n    </section>\n\n    <h2>CÁC DÒNG SẢN PHẨM</h2>\n\n    <table class=\"venus-price-table\">\n        <thead>\n            <tr>\n                <th>Nhóm sản phẩm</th>\n                <th>Đặc điểm</th>\n                <th>Báo giá</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td>Đồng phục công sở</td>\n                <td>Áo sơ mi, quần âu, chân váy, vest</td>\n                <td>Liên hệ</td>\n            </tr>\n            <tr>\n                <td>Đồng phục y tế</td>\n                <td>Áo blouse, bộ scrub, đồng phục phòng khám</td>\n                <td>Liên hệ</td>\n            </tr>\n            <tr>\n                <td>Đồng phục nhà hàng</td>\n                <td>Áo bếp, tạp dề, đồng phục phục vụ</td>\n                <td>Liên hệ</td>\n            </tr>\n            <tr>\n                <td>Đồng phục bảo hộ</td>\n                <td>Quần áo bảo hộ, áo phản quang</td>\n                <td>Liên hệ</td>\n            </tr>\n            <tr>\n                <td>Áo thun đồng phục</td>\n                <td>Áo polo, áo cổ tròn, áo sự kiện</td>\n                <td>Liên hệ</td>\n            </tr>\n            <tr>\n                <td>Đồng phục trường học</td>\n                <td>Áo lớp, đồng phục học sinh</td>\n                <td>Liên hệ</td>\n            </tr>\n        </tbody>\n    </table>\n\n    <h2>NHỮNG YẾU TỐ ẢNH HƯỞNG ĐẾN GIÁ</h2>\n\n    <div class=\"venus-price-note\">\n        <strong>Chất liệu vải:</strong> Loại vải, độ dày, thành phần và đặc tính sử dụng.<br>\n        <strong>Số lượng đặt hàng:</strong> Số lượng sản phẩm trong mỗi đơn hàng.<br>\n        <strong>Thiết kế:</strong> Kiểu dáng, màu sắc và mức độ phức tạp.<br>\n        <strong>In và thêu logo:</strong> Kích thước, vị trí và phương pháp thực hiện.<br>\n        <strong>Yêu cầu riêng:</strong> Tiến độ sản xuất, đóng gói và giao hàng.\n    </div>\n\n    <h2>QUY TRÌNH NHẬN BÁO GIÁ</h2>\n\n    <ol>\n        <li>Khách hàng gửi yêu cầu về loại đồng phục và số lượng.</li>\n        <li>VENUS UNIFORM tư vấn chất liệu, kiểu dáng và phương án thiết kế.</li>\n        <li>Hai bên thống nhất mẫu mã và yêu cầu sản xuất.</li>\n        <li>VENUS UNIFORM gửi báo giá chi tiết cho khách hàng.</li>\n    </ol>\n\n    <section class=\"venus-price-cta\">\n        <h2>BẠN ĐANG CẦN BÁO GIÁ ĐỒNG PHỤC?</h2>\n        <p>Hãy gửi yêu cầu để đội ngũ VENUS UNIFORM hỗ trợ tư vấn và báo giá phù hợp.</p>\n        <a href=\"/dongphuc/lien-he/\">LIÊN HỆ TƯ VẤN</a>\n    </section>\n</div>\n<!-- /wp:html -->','Bảng giá','','publish','closed','closed','','bang-gia','','','2026-11-03 15:52:49','2026-11-03 15:52:49','',0,'http://localhost/dongphuc/?page_id=30',0,'page','',0),(31,1,'2026-10-01 07:49:17','2026-10-01 07:49:17','<!-- wp:paragraph -->\n<p>Bảng giá dịch vụ (sẽ cập nhật)</p>\n<!-- /wp:paragraph -->','Bảng giá','','inherit','closed','closed','','30-revision-v1','','','2026-10-01 07:49:17','2026-10-01 07:49:17','',30,'http://localhost/dongphuc/?p=31',0,'revision','',0),(32,1,'2026-10-01 07:49:43','2026-10-01 07:49:43','<!-- wp:heading {\"level\":1,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|ast-global-color-8\"}}}},\"textColor\":\"ast-global-color-8\",\"fontSize\":\"large\"} -->\n<h1 class=\"wp-block-heading has-ast-global-color-8-color has-text-color has-link-color has-large-font-size\"><strong>ĐẶT LỊCH TƯ VẤN</strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Đội ngũ chuyên gia của chúng tôi sẵn sàng mang mẫu vải tận nơi, tư vấn giải pháp thiết kế &amp; tối ưu chi phí sản xuất cho doanh nghiệp của bạn.</p>\n<!-- /wp:p