  `user_id` bigint(20) unsigned NOT NULL DEFAULT 0,
  `staff_id` bigint(20) unsigned NOT NULL DEFAULT 0,
  `payment_id` bigint(20) unsigned NOT NULL DEFAULT 0,
  `async_action_id` bigint(20) unsigned NOT NULL DEFAULT 0,
  `date_created` datetime DEFAULT NULL,
  `action` varchar(32) NOT NULL DEFAULT '',
  `action_title` tinytext NOT NULL,
  `action_summary` text NOT NULL,
  `summary_vars` text NOT NULL,
  `context` varchar(32) NOT NULL DEFAULT '',
  `sub_context` varchar(32) NOT NULL DEFAULT '',
  `stack_trace` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appointment_id` (`appointment_id`),
  KEY `appointment_type_id` (`appointment_type_id`),
  KEY `user_id` (`user_id`),
  KEY `staff_id` (`staff_id`),
  KEY `async_action_id` (`async_action_id`),
  KEY `date_created` (`date_created`),
  KEY `action` (`action`),
  KEY `context` (`context`),
  KEY `sub_context` (`sub_context`)
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Created with schema v3.7.6 (2026-10-11 04:16:15)';
